import React from 'react';
import Background from '../components/Background';
import MeshSphere from '../components/MeshSphere';
import { useMoods, useThoughts } from '../hooks/useStorage';

const MOOD_COLORS = {1:'#d07070',2:'#c89060',3:'#b8a860',4:'#70a880',5:'#6090c0'};
const MOOD_GRADS  = {
  1:'linear-gradient(135deg, rgba(210,170,170,0.8) 0%, rgba(195,160,175,0.75) 100%)',
  2:'linear-gradient(135deg, rgba(215,185,160,0.8) 0%, rgba(205,175,180,0.75) 100%)',
  3:'linear-gradient(135deg, rgba(195,188,215,0.8) 0%, rgba(205,195,210,0.75) 100%)',
  4:'linear-gradient(135deg, rgba(170,198,212,0.8) 0%, rgba(180,205,215,0.75) 100%)',
  5:'linear-gradient(135deg, rgba(170,205,195,0.8) 0%, rgba(180,215,210,0.75) 100%)',
};

export default function History({ setPage }) {
  const { moods, streak, avgMood } = useMoods();
  const { thoughts, trapCounts }   = useThoughts();
  const isEmpty = moods.length===0 && thoughts.length===0;
  const maxTrap = Math.max(...Object.values(trapCounts),1);
  const avgEmoji = ['','😔','😟','😐','🙂','😄'];

  if (isEmpty) return (
    <div style={{ minHeight:'100vh', paddingTop:56, paddingBottom:96, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', padding:'80px 22px', position:'relative' }}>
      <Background mood="default" />
      <div style={{ position:'relative', zIndex:1, textAlign:'center' }}>
        <div style={{ display:'flex', justifyContent:'center', marginBottom:24 }}>
          <MeshSphere size={200} speed={0.3} distort={0.4} />
        </div>
        <h2 style={{ fontSize:28, fontWeight:700, color:'#1c1917', marginBottom:10, letterSpacing:'-0.03em' }}>Ingen historik än</h2>
        <p style={{ fontSize:14, color:'rgba(28,25,23,0.5)', marginBottom:32, fontWeight:300, maxWidth:250, margin:'0 auto 32px' }}>Börja med att analysera en tanke eller göra din första check-in.</p>
        <div style={{ display:'flex', gap:10, justifyContent:'center' }}>
          <button onClick={()=>setPage('home')} style={{ padding:'13px 24px', borderRadius:100, background:'#1c1917', color:'#f0ece6', fontSize:13, fontWeight:600, border:'none', boxShadow:'0 4px 20px rgba(0,0,0,0.18)' }}>Analysera en tanke</button>
          <button onClick={()=>setPage('checkin')} style={{ padding:'13px 24px', borderRadius:100, background:'rgba(255,255,255,0.65)', border:'1px solid rgba(255,255,255,0.85)', color:'rgba(28,25,23,0.65)', fontSize:13, backdropFilter:'blur(12px)' }}>Check-in</button>
        </div>
      </div>
    </div>
  );

  return (
    <div style={{ minHeight:'100vh', paddingTop:56, paddingBottom:96, position:'relative' }}>
      <Background mood="default" />
      <div style={{ position:'relative', zIndex:1, padding:'24px 22px', maxWidth:480, margin:'0 auto', animation:'fadeUp .7s cubic-bezier(0.16,1,0.3,1) both' }}>

        <p style={{ fontSize:12, color:'rgba(28,25,23,0.4)', fontWeight:500, textTransform:'uppercase', letterSpacing:'0.04em', marginBottom:8 }}>Din historik</p>
        <h1 style={{ fontSize:'clamp(32px,8vw,50px)', fontWeight:700, letterSpacing:'-0.04em', color:'#1c1917', marginBottom:24, lineHeight:1.05 }}>
          Hur har det<br/><span style={{ fontStyle:'italic', fontWeight:300, color:'rgba(28,25,23,0.4)' }}>gått?</span>
        </h1>

        {/* Stats */}
        <div style={{ display:'grid', gridTemplateColumns:'repeat(3,1fr)', gap:8, marginBottom:12 }}>
          {[
            { val:streak, label:'Streak', suf:' dagar' },
            { val:thoughts.length, label:'Analyser', suf:'' },
            { val:avgMood>0?`${avgEmoji[Math.round(avgMood)]} ${avgMood}`:'—', label:'Snitt humör', suf:'' },
          ].map(({val,label,suf})=>(
            <div key={label} style={{ background:'rgba(255,255,255,0.65)', backdropFilter:'blur(16px)', borderRadius:18, padding:'14px 12px', textAlign:'center', border:'1px solid rgba(255,255,255,0.85)', boxShadow:'0 2px 10px rgba(0,0,0,0.05)' }}>
              <div style={{ fontSize:22, fontWeight:700, letterSpacing:'-0.03em', color:'#1c1917', lineHeight:1, marginBottom:4 }}>{val}<span style={{ fontSize:10, color:'rgba(28,25,23,0.4)', fontWeight:400 }}>{suf}</span></div>
              <div style={{ fontSize:10, color:'rgba(28,25,23,0.45)', fontWeight:500, textTransform:'uppercase', letterSpacing:'0.04em' }}>{label}</div>
            </div>
          ))}
        </div>

        {/* Mood chart */}
        {moods.length>0 && (
          <div style={{ background:'rgba(255,255,255,0.65)', backdropFilter:'blur(16px)', borderRadius:20, padding:'16px 18px', marginBottom:10, border:'1px solid rgba(255,255,255,0.85)', boxShadow:'0 2px 12px rgba(0,0,0,0.05)' }}>
            <p style={{ fontSize:11, fontWeight:500, textTransform:'uppercase', letterSpacing:'0.06em', color:'rgba(28,25,23,0.4)', marginBottom:14 }}>Humör · Trend</p>
            <div style={{ display:'flex', alignItems:'flex-end', gap:4, height:64 }}>
              {[...moods].reverse().map((m,i)=>(
                <div key={i} style={{ flex:1, display:'flex', flexDirection:'column', alignItems:'center', gap:2, height:'100%', justifyContent:'flex-end' }}>
                  <div style={{ width:'100%', borderRadius:'4px 4px 0 0', background:MOOD_COLORS[m.score], height:`${(m.score/5)*100}%`, minHeight:4, opacity:0.75 }} />
                  <span style={{ fontSize:6, color:'rgba(28,25,23,0.3)', whiteSpace:'nowrap' }}>
                    {new Date(m.date).toLocaleDateString('sv-SE',{day:'2-digit',month:'2-digit'})}
                  </span>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Trap freq */}
        {Object.keys(trapCounts).length>0 && (
          <div style={{ background:'rgba(255,255,255,0.65)', backdropFilter:'blur(16px)', borderRadius:20, padding:'16px 18px', marginBottom:10, border:'1px solid rgba(255,255,255,0.85)', boxShadow:'0 2px 12px rgba(0,0,0,0.05)' }}>
            <p style={{ fontSize:11, fontWeight:500, textTransform:'uppercase', letterSpacing:'0.06em', color:'rgba(28,25,23,0.4)', marginBottom:14 }}>Tankefällor</p>
            {Object.entries(trapCounts).sort((a,b)=>b[1]-a[1]).map(([label,count])=>(
              <div key={label} style={{ display:'flex', alignItems:'center', gap:10, marginBottom:10 }}>
                <span style={{ fontSize:13, color:'rgba(28,25,23,0.7)', flex:1, fontWeight:300 }}>{label}</span>
                <div style={{ width:72, height:3, background:'rgba(0,0,0,0.06)', borderRadius:2 }}>
                  <div style={{ height:'100%', borderRadius:2, background:'rgba(28,25,23,0.3)', width:`${(count/maxTrap)*100}%` }} />
                </div>
                <span style={{ fontSize:12, color:'rgba(28,25,23,0.4)', width:16, textAlign:'right', fontWeight:500 }}>{count}</span>
              </div>
            ))}
          </div>
        )}

        {/* Thought entries */}
        {thoughts.length>0 && (
          <>
            <p style={{ fontSize:11, fontWeight:500, textTransform:'uppercase', letterSpacing:'0.06em', color:'rgba(28,25,23,0.4)', margin:'18px 0 10px' }}>Tidigare analyser</p>
            {thoughts.map(th=>(
              <div key={th.id} style={{ background:'rgba(255,255,255,0.6)', backdropFilter:'blur(14px)', borderRadius:18, padding:'14px 18px', marginBottom:8, border:'1px solid rgba(255,255,255,0.82)', boxShadow:'0 2px 10px rgba(0,0,0,0.04)' }}>
                <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:7 }}>
                  <span style={{ fontSize:12, fontWeight:500, color:'rgba(28,25,23,0.6)' }}>{th.trap_icon||'→'} {th.trap_label}</span>
                  <span style={{ fontSize:11, color:'rgba(28,25,23,0.3)' }}>{new Date(th.date).toLocaleDateString('sv-SE',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}</span>
                </div>
                <p style={{ fontSize:12, color:'rgba(28,25,23,0.4)', fontStyle:'italic', marginBottom:8, lineHeight:1.65 }}>"{th.user_text?.slice(0,90)}{th.user_text?.length>90?'...':''}"</p>
                <p style={{ fontSize:13, color:'rgba(28,25,23,0.7)', lineHeight:1.75, fontWeight:300 }}>{th.reframe}</p>
              </div>
            ))}
          </>
        )}
      </div>
    </div>
  );
}
